IF OBJECT_ID('cms_records') IS NULL CREATE TABLE cms_records(collection NVARCHAR(32) NOT NULL,id NVARCHAR(64) NOT NULL,updated_at NVARCHAR(40) NOT NULL,document NVARCHAR(MAX) NOT NULL,CONSTRAINT pk_cms_records PRIMARY KEY(collection,id));
IF OBJECT_ID('cms_revisions') IS NULL CREATE TABLE cms_revisions(collection NVARCHAR(32) NOT NULL,id NVARCHAR(64) NOT NULL,version INT NOT NULL,document NVARCHAR(MAX) NOT NULL,CONSTRAINT pk_cms_revisions PRIMARY KEY(collection,id,version));
IF OBJECT_ID('cms_audit') IS NULL CREATE TABLE cms_audit(id NVARCHAR(64) PRIMARY KEY,created_at NVARCHAR(40) NOT NULL,document NVARCHAR(MAX) NOT NULL);
IF OBJECT_ID('cms_releases') IS NULL CREATE TABLE cms_releases(id NVARCHAR(64) PRIMARY KEY,request_key NVARCHAR(100) NOT NULL UNIQUE,created_at NVARCHAR(40) NOT NULL,document NVARCHAR(MAX) NOT NULL,snapshot NVARCHAR(MAX) NOT NULL);
IF OBJECT_ID('automation_processes') IS NULL CREATE TABLE automation_processes(id NVARCHAR(64) NOT NULL,version INT NOT NULL,document NVARCHAR(MAX) NOT NULL,CONSTRAINT pk_automation_processes PRIMARY KEY(id,version));
IF OBJECT_ID('automation_runs') IS NULL CREATE TABLE automation_runs(id NVARCHAR(64) PRIMARY KEY,environment NVARCHAR(16) NOT NULL,process_id NVARCHAR(64) NOT NULL,created_at NVARCHAR(40) NOT NULL,status NVARCHAR(24) NOT NULL,document NVARCHAR(MAX) NOT NULL);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='ix_automation_runs_env' AND object_id=OBJECT_ID('automation_runs')) CREATE INDEX ix_automation_runs_env ON automation_runs(environment,created_at,id);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='ix_automation_runs_list' AND object_id=OBJECT_ID('automation_runs')) CREATE INDEX ix_automation_runs_list ON automation_runs(environment,process_id,status,created_at DESC,id DESC);
IF OBJECT_ID('automation_commands') IS NULL CREATE TABLE automation_commands(environment NVARCHAR(16) NOT NULL,actor_id NVARCHAR(128) NOT NULL,request_key NVARCHAR(100) NOT NULL,input_hash NVARCHAR(64) NOT NULL,document NVARCHAR(MAX) NOT NULL,CONSTRAINT pk_automation_commands PRIMARY KEY(environment,actor_id,request_key));
IF OBJECT_ID('agent_keys') IS NULL CREATE TABLE agent_keys(id NVARCHAR(64) PRIMARY KEY,key_hash NVARCHAR(64) NOT NULL,document NVARCHAR(MAX) NOT NULL);
IF OBJECT_ID('agent_requests') IS NULL CREATE TABLE agent_requests(agent_id NVARCHAR(128) NOT NULL,request_key NVARCHAR(200) NOT NULL,input_hash NVARCHAR(64) NOT NULL,document NVARCHAR(MAX) NOT NULL,CONSTRAINT pk_agent_requests PRIMARY KEY(agent_id,request_key));
IF OBJECT_ID('submissions') IS NULL CREATE TABLE submissions(id NVARCHAR(64) PRIMARY KEY,updated_at NVARCHAR(40) NOT NULL,document NVARCHAR(MAX) NOT NULL);
IF OBJECT_ID('submission_comments') IS NULL CREATE TABLE submission_comments(id NVARCHAR(64) PRIMARY KEY,submission_id NVARCHAR(64) NOT NULL,created_at NVARCHAR(40) NOT NULL,document NVARCHAR(MAX) NOT NULL);